        [Fact]
        public void ThermalTransmittance_QuantityInfo_ReturnsQuantityInfoDescribingQuantity()
        {
            ThermalTransmittanceUnit[] unitsOrderedByName = EnumHelper.GetValues<ThermalTransmittanceUnit>().OrderBy(x => x.ToString(), StringComparer.OrdinalIgnoreCase).ToArray();
            var quantity = new ThermalTransmittance(1, ThermalTransmittanceUnit.KilowattPerSquareMeterKelvin);

            QuantityInfo<ThermalTransmittance, ThermalTransmittanceUnit> quantityInfo = quantity.QuantityInfo;

            Assert.Equal("ThermalTransmittance", quantityInfo.Name);
            Assert.Equal(ThermalTransmittance.Zero, quantityInfo.Zero);
            Assert.Equal(ThermalTransmittance.BaseUnit, quantityInfo.BaseUnitInfo.Value);
            Assert.Equal(unitsOrderedByName, quantityInfo.Units);
            Assert.Equal(unitsOrderedByName, quantityInfo.UnitInfos.Select(x => x.Value));
            Assert.Equal(ThermalTransmittance.Info, quantityInfo);
            Assert.Equal(quantityInfo, ((IQuantity)quantity).QuantityInfo);
            Assert.Equal(quantityInfo, ((IQuantity<ThermalTransmittanceUnit>)quantity).QuantityInfo);
        }

        [Fact]
        public void ThermalTransmittanceInfo_CreateWithCustomUnitInfos()
        {
            ThermalTransmittanceUnit[] expectedUnits = [ThermalTransmittanceUnit.KilowattPerSquareMeterKelvin];

            ThermalTransmittance.ThermalTransmittanceInfo quantityInfo = ThermalTransmittance.ThermalTransmittanceInfo.CreateDefault(mappings => mappings.SelectUnits(expectedUnits));

            Assert.Equal("ThermalTransmittance", quantityInfo.Name);
            Assert.Equal(ThermalTransmittance.Zero, quantityInfo.Zero);
            Assert.Equal(ThermalTransmittance.BaseUnit, quantityInfo.BaseUnitInfo.Value);
            Assert.Equal(expectedUnits, quantityInfo.Units);
            Assert.Equal(expectedUnits, quantityInfo.UnitInfos.Select(x => x.Value));
        }

        [Fact]
        public void KilowattPerSquareMeterKelvinToThermalTransmittanceUnits()
        {
            ThermalTransmittance kilowattpersquaremeterkelvin = ThermalTransmittance.FromKilowattsPerSquareMeterKelvin(1);
            AssertEx.EqualTolerance(BtusPerHourSquareFeetDegreeFahrenheitInOneKilowattPerSquareMeterKelvin, kilowattpersquaremeterkelvin.BtusPerHourSquareFeetDegreeFahrenheit, BtusPerHourSquareFeetDegreeFahrenheitTolerance);
            AssertEx.EqualTolerance(KilocaloriesPerSquareCentimeterHourDegreeCelsiusInOneKilowattPerSquareMeterKelvin, kilowattpersquaremeterkelvin.KilocaloriesPerSquareCentimeterHourDegreeCelsius, KilocaloriesPerSquareCentimeterHourDegreeCelsiusTolerance);
            AssertEx.EqualTolerance(KilowattsPerSquareMeterKelvinInOneKilowattPerSquareMeterKelvin, kilowattpersquaremeterkelvin.KilowattsPerSquareMeterKelvin, KilowattsPerSquareMeterKelvinTolerance);
            AssertEx.EqualTolerance(WattsPerSquareCentimeterKelvinInOneKilowattPerSquareMeterKelvin, kilowattpersquaremeterkelvin.WattsPerSquareCentimeterKelvin, WattsPerSquareCentimeterKelvinTolerance);
            AssertEx.EqualTolerance(WattsPerSquareMeterDegreeCelsiusInOneKilowattPerSquareMeterKelvin, kilowattpersquaremeterkelvin.WattsPerSquareMeterDegreeCelsius, WattsPerSquareMeterDegreeCelsiusTolerance);
            AssertEx.EqualTolerance(WattsPerSquareMeterKelvinInOneKilowattPerSquareMeterKelvin, kilowattpersquaremeterkelvin.WattsPerSquareMeterKelvin, WattsPerSquareMeterKelvinTolerance);
            AssertEx.EqualTolerance(WattsPerSquareMillimeterKelvinInOneKilowattPerSquareMeterKelvin, kilowattpersquaremeterkelvin.WattsPerSquareMillimeterKelvin, WattsPerSquareMillimeterKelvinTolerance);
        }

