        [Theory]
        [MemberData(nameof(UnitTypes))]
        public void ToUnit(ThermalTransmittanceUnit unit)
        {
            var inBaseUnits = ThermalTransmittance.From(1.0, ThermalTransmittance.BaseUnit);
