        [Theory]
        [MemberData(nameof(UnitTypes))]
        public void ToUnit_FromIQuantity_ReturnsTheExpectedIQuantity(ThermalTransmittanceUnit unit)
        {
            var quantity = ThermalTransmittance.From(3, ThermalTransmittance.BaseUnit);
            ThermalTransmittance expectedQuantity = quantity.ToUnit(unit);
            Assert.Multiple(() =>
            {
                IQuantity<ThermalTransmittanceUnit> quantityToConvert = quantity;
                IQuantity<ThermalTransmittanceUnit> convertedQuantity = quantityToConvert.ToUnit(unit);
                Assert.Equal(unit, convertedQuantity.Unit);
                Assert.Equal(expectedQuantity, convertedQuantity);
            }, () =>
            {
