                IQuantity convertedQuantity = quantityToConvert.ToUnit(unit);
                Assert.Equal(unit, convertedQuantity.Unit);
                Assert.Equal(expectedQuantity, convertedQuantity);
            });
        }

        [Fact]
        public void ConversionRoundTrip()
        {
            ThermalTransmittance kilowattpersquaremeterkelvin = ThermalTransmittance.FromKilowattsPerSquareMeterKelvin(3);
            Assert.Equal(3, ThermalTransmittance.FromBtusPerHourSquareFeetDegreeFahrenheit(kilowattpersquaremeterkelvin.BtusPerHourSquareFeetDegreeFahrenheit).KilowattsPerSquareMeterKelvin);
            Assert.Equal(3, ThermalTransmittance.FromKilocaloriesPerSquareCentimeterHourDegreeCelsius(kilowattpersquaremeterkelvin.KilocaloriesPerSquareCentimeterHourDegreeCelsius).KilowattsPerSquareMeterKelvin);
            Assert.Equal(3, ThermalTransmittance.FromKilowattsPerSquareMeterKelvin(kilowattpersquaremeterkelvin.KilowattsPerSquareMeterKelvin).KilowattsPerSquareMeterKelvin);
            Assert.Equal(3, ThermalTransmittance.FromWattsPerSquareCentimeterKelvin(kilowattpersquaremeterkelvin.WattsPerSquareCentimeterKelvin).KilowattsPerSquareMeterKelvin);
            Assert.Equal(3, ThermalTransmittance.FromWattsPerSquareMeterDegreeCelsius(kilowattpersquaremeterkelvin.WattsPerSquareMeterDegreeCelsius).KilowattsPerSquareMeterKelvin);
            Assert.Equal(3, ThermalTransmittance.FromWattsPerSquareMeterKelvin(kilowattpersquaremeterkelvin.WattsPerSquareMeterKelvin).KilowattsPerSquareMeterKelvin);
            Assert.Equal(3, ThermalTransmittance.FromWattsPerSquareMillimeterKelvin(kilowattpersquaremeterkelvin.WattsPerSquareMillimeterKelvin).KilowattsPerSquareMeterKelvin);
        }

        [Fact]
        public void ArithmeticOperators()
        {
            ThermalTransmittance v = ThermalTransmittance.FromKilowattsPerSquareMeterKelvin(1);
            Assert.Equal(-1, -v.KilowattsPerSquareMeterKelvin);
            Assert.Equal(2, (ThermalTransmittance.FromKilowattsPerSquareMeterKelvin(3) - v).KilowattsPerSquareMeterKelvin);
            Assert.Equal(2, (v + v).KilowattsPerSquareMeterKelvin);
            Assert.Equal(10, (v * 10).KilowattsPerSquareMeterKelvin);
            Assert.Equal(10, (10 * v).KilowattsPerSquareMeterKelvin);
            Assert.Equal(2, (ThermalTransmittance.FromKilowattsPerSquareMeterKelvin(10) / 5).KilowattsPerSquareMeterKelvin);
            Assert.Equal(2, ThermalTransmittance.FromKilowattsPerSquareMeterKelvin(10) / ThermalTransmittance.FromKilowattsPerSquareMeterKelvin(5));
        }

        [Fact]
        public void ComparisonOperators()
        {
            ThermalTransmittance oneKilowattPerSquareMeterKelvin = ThermalTransmittance.FromKilowattsPerSquareMeterKelvin(1);
            ThermalTransmittance twoKilowattsPerSquareMeterKelvin = ThermalTransmittance.FromKilowattsPerSquareMeterKelvin(2);

            Assert.True(oneKilowattPerSquareMeterKelvin < twoKilowattsPerSquareMeterKelvin);
            Assert.True(oneKilowattPerSquareMeterKelvin <= twoKilowattsPerSquareMeterKelvin);
            Assert.True(twoKilowattsPerSquareMeterKelvin > oneKilowattPerSquareMeterKelvin);
            Assert.True(twoKilowattsPerSquareMeterKelvin >= oneKilowattPerSquareMeterKelvin);

            Assert.False(oneKilowattPerSquareMeterKelvin > twoKilowattsPerSquareMeterKelvin);
            Assert.False(oneKilowattPerSquareMeterKelvin >= twoKilowattsPerSquareMeterKelvin);
            Assert.False(twoKilowattsPerSquareMeterKelvin < oneKilowattPerSquareMeterKelvin);
            Assert.False(twoKilowattsPerSquareMeterKelvin <= oneKilowattPerSquareMeterKelvin);
        }

