        [Theory]
        [InlineData(1, ThermalTransmittanceUnit.KilowattPerSquareMeterKelvin, 1, ThermalTransmittanceUnit.KilowattPerSquareMeterKelvin, true)]  // Same value and unit.
        [InlineData(1, ThermalTransmittanceUnit.KilowattPerSquareMeterKelvin, 2, ThermalTransmittanceUnit.KilowattPerSquareMeterKelvin, false)] // Different value.
        public void Equals_ReturnsTrue_IfValueAndUnitAreEqual(double valueA, ThermalTransmittanceUnit unitA, double valueB, ThermalTransmittanceUnit unitB, bool expectEqual)
        {
            var a = new ThermalTransmittance(valueA, unitA);
            var b = new ThermalTransmittance(valueB, unitB);

            // Operator overloads.
            Assert.Equal(expectEqual, a == b);
            Assert.Equal(expectEqual, b == a);
            Assert.Equal(!expectEqual, a != b);
            Assert.Equal(!expectEqual, b != a);

            // IEquatable<T>
            Assert.Equal(expectEqual, a.Equals(b));
            Assert.Equal(expectEqual, b.Equals(a));

            // IEquatable
            Assert.Equal(expectEqual, a.Equals((object)b));
            Assert.Equal(expectEqual, b.Equals((object)a));
        }

        [Fact]
        public void Equals_Null_ReturnsFalse()
        {
            var a = ThermalTransmittance.Zero;

            Assert.False(a.Equals((object)null));

            // "The result of the expression is always 'false'..."
            #pragma warning disable CS8073
            Assert.False(a == null);
            Assert.False(null == a);
            Assert.True(a != null);
            Assert.True(null != a);
            #pragma warning restore CS8073
        }

