            Assert.Equal("1 Btu/Hrft²°F", new ThermalTransmittance(1, ThermalTransmittanceUnit.BtuPerHourSquareFeetDegreeFahrenheit).ToString());
            Assert.Equal("1 kcal/cm²Hr°C", new ThermalTransmittance(1, ThermalTransmittanceUnit.KilocaloriePerSquareCentimeterHourDegreeCelsius).ToString());
            Assert.Equal("1 kW/m²K", new ThermalTransmittance(1, ThermalTransmittanceUnit.KilowattPerSquareMeterKelvin).ToString());
            Assert.Equal("1 W/cm²K", new ThermalTransmittance(1, ThermalTransmittanceUnit.WattPerSquareCentimeterKelvin).ToString());
