        [Fact]
        public void ToString_WithSwedishCulture_ReturnsUnitAbbreviationForEnglishCultureSinceThereAreNoMappings()
        {
            // Chose this culture, because we don't currently have any abbreviations mapped for that culture and we expect the en-US to be used as fallback.
            var swedishCulture = CultureInfo.GetCultureInfo("sv-SE");

            Assert.Equal("1 Btu/Hrft²°F", new ThermalTransmittance(1, ThermalTransmittanceUnit.BtuPerHourSquareFeetDegreeFahrenheit).ToString(swedishCulture));
            Assert.Equal("1 kcal/cm²Hr°C", new ThermalTransmittance(1, ThermalTransmittanceUnit.KilocaloriePerSquareCentimeterHourDegreeCelsius).ToString(swedishCulture));
            Assert.Equal("1 kW/m²K", new ThermalTransmittance(1, ThermalTransmittanceUnit.KilowattPerSquareMeterKelvin).ToString(swedishCulture));
            Assert.Equal("1 W/cm²K", new ThermalTransmittance(1, ThermalTransmittanceUnit.WattPerSquareCentimeterKelvin).ToString(swedishCulture));
            Assert.Equal("1 W/m²°C", new ThermalTransmittance(1, ThermalTransmittanceUnit.WattPerSquareMeterDegreeCelsius).ToString(swedishCulture));
            Assert.Equal("1 W/m²K", new ThermalTransmittance(1, ThermalTransmittanceUnit.WattPerSquareMeterKelvin).ToString(swedishCulture));
            Assert.Equal("1 W/mm²K", new ThermalTransmittance(1, ThermalTransmittanceUnit.WattPerSquareMillimeterKelvin).ToString(swedishCulture));
        }

